388			},
389			"duplicate disabled id": {
390				App: "app", Revision: "r1", Image: "img", BatchSize: 2,
391				Clusters: []Cluster{
392					{ID: "dup", Tags: map[string]string{"env": "prod"}},
393					{ID: "dup", Disabled: true, Tags: map[string]string{"env": "temp"}},
394				},
395			},
396		}
397		for name, in := range cases {
398			t.Run(name, func(t *testing.T) {
399				before := cloneInput(in)
400				orderBefore := candidateIDs(in)
401				plan, err := MakeReleasePlan(in)
402				if err == nil {
403					t.Fatal("expected a failed computation")
404				}
405				assertZeroReleasePlan(t, plan)
406				if got := candidateIDs(in); !reflect.DeepEqual(got, orderBefore) {
