411				}
412			})
413		}
414	}
415	
416	// TestValidate_EmptyCandidatesKeepsOperationsDistinct pins the distinction
417	// between the two public operations when every other field is legal: standalone
418	// validation SUCCEEDS on an empty candidate list (the config is well-formed),
419	// while actually planning fails with "未提供候选集群" and the zero-value plan.
420	// Both nil and a non-nil empty slice are empty candidate lists.
421	func TestValidate_EmptyCandidatesKeepsOperationsDistinct(t *testing.T) {
