package darksafe

import (
	"fmt"
	"reflect"
	"strings"
	"testing"
)

// This file is a regression net for the conjunction semantics of multi-label
// exclude conditions, driven through the public planning result
// (MakeReleasePlan / ParseReleaseInput), never the internal matchers.
//
// The distinction under protection:
//
//   - One exclude condition can demand several labels; a cluster matches that
//     condition only when ALL of its key-value pairs match (logical AND).
//   - The exclude array is a logical OR: one FULLY matched condition excludes.
//     A cluster must never be excluded because a single label happens to fit,
//     nor may matching pieces of DISTINCT conditions be stitched into one hit.
//   - A cluster that fully matches two conditions still leaves the candidate
//     set exactly once, with one excluded record.
//
// Also pinned here: adding irrelevant tags changes nothing; label keys and
// values stay exact-string comparisons; a missing key is distinguished from a
// present-but-empty value; and the fixed disabled → exclude → include priority
// (README §5) holds for multi-label conditions as it does for single-label
// ones. The planning-result conventions — ascending scheduling order, ascending
// excluded-record order, chunk batching, zero-plan failure with all reasons —
// are exercised against the same semantics.

// multiLabelExcludeDoc builds a release document around two two-label exclude
// conditions:
//
//	{"env": "prod", "quarantine": "true"}
//	{"region": "west", "tier": "edge"}
//
// plus a single-label include {"env":"prod"}. Clusters are written in the
// exact tag-situation the caller supplies; the document's cluster order is
// deliberately shuffled relative to ID order to prove the result does not
// depend on write order.
func multiLabelExcludeDoc(clusters string) string {
	return fmt.Sprintf(`{
  "app": "app",
  "revision": "r1",
  "image": "img",
  "batchSize": 2,
  "include": [{"env": "prod"}],
  "exclude": [
    {"env": "prod", "quarantine": "true"},
    {"region": "west", "tier": "edge"}
  ],
  "clusters": %s
}`, clusters)
}

// selectedIDs reports the selected cluster IDs in scheduled (batch) order.
func selectedIDs(plan ReleasePlan) []string {
	var out []string
	for _, b := range plan.Batches {
		out = append(out, b.Clusters...)
	}
	return out
}

// assertExcludedReasons fails unless plan.Excluded equals exactly the wanted
// {id, reason} pairs in the given (ascending-ID) order.
func assertExcludedReasons(t *testing.T, plan ReleasePlan, want []ExcludedCluster) {
	t.Helper()
	if !reflect.DeepEqual(plan.Excluded, want) {
		t.Fatalf("excluded records mismatch:\n got %+v\nwant %+v", plan.Excluded, want)
	}
}

// assertNotInAnyBatch fails if any of the given IDs appears in a batch.
func assertNotInAnyBatch(t *testing.T, plan ReleasePlan, ids ...string) {
	t.Helper()
	inBatch := map[string]bool{}
	for _, b := range plan.Batches {
		for _, id := range b.Clusters {
			inBatch[id] = true
		}
	}
	for _, id := range include {
		if inBatch[id] {
			t.Fatalf("excluded cluster %q must not appear in any batch: %+v", id, plan.Batches)
		}
	}
}

// TestExclude_MultiLabelConditionRequiresAllPairs is the headline regression:
// a partial match must not exclude.
//
//   - partial1: only env=prod (quarantine absent) — must NOT be excluded.
//   - partial2: env=prod + region=west, the two OTHER labels absent — matches
//     one piece of EACH condition but neither fully; must NOT be excluded
//     (no stitching pieces across distinct conditions).
//   - full1: env=prod + quarantine=true — fully matches condition 1 → excluded.
//   - full2: region=west + tier=edge — fully matches condition 2 → excluded.
//   - irrelevant: fully matches cond1 and carries extra unrelated tags →
//     excluded anyway; irrelevant tags do not rescue or alter the decision.
//   - near-miss: env=Prod (case difference), quarantine=true — no exact match.
//   - disabled: fully matches cond1 but is disabled — priority says disabled.
//
// All clusters carry env=prod so the include is satisfied wherever relevant;
// only the exclude (and disabled) decisions separate them.
func TestExclude_MultiLabelConditionRequiresAllPairs(t *testing.T) {
	doc := multiLabelExcludeDoc(`[
    {"id": "full2", "tags": {"region": "west", "tier": "edge"}},
    {"id": "partial1", "tags": {"env": "prod"}},
    {"id": "full1", "tags": {"env": "prod", "quarantine": "true"}},
    {"id": "near-miss", "tags": {"env": "Prod", "quarantine": "true", "region": "west", "tier": "edge"}},
    {"id": "partial2", "tags": {"env": "prod", "region": "west"}},
    {"id": "irrelevant", "tags": {"env": "prod", "quarantine": "true", "zone": "z9", "note": "x"}},
    {"id": "disabled", "disabled": true, "tags": {"env": "prod", "quarantine": "true"}}
  ]`)
	plan, err := MakeReleasePlan(parsePlan(t, doc))
	if err != nil {
		t.Fatal(err)
	}

	// Selected: near-miss fails BOTH excludes exactly but has env=Prod, so it
	// also fails the include — it is not selected. partial1/partial2 satisfy
	// env=prod and no full exclude → selected. near-miss goes to excluded with
	// ReasonIncludeNotMatched, not ReasonExcludeMatched.
	if got, want := selectedIDs(plan), []string{"partial1", "partial2"}; !reflect.DeepEqual(got, want) {
		t.Fatalf("selected = %v, want %v", got, want)
	}
	assertNotInAnyBatch(t, plan, "full1", "full2", "irrelevant", "near-miss", "disabled")

	assertExcludedReasons(t, plan, []ExcludedCluster{
		{ID: "disabled", Reason: ReasonDisabled},
		{ID: "full1", Reason: ReasonExcludeMatched},
		{ID: "full2", Reason: ReasonExcludeMatched},
		{ID: "irrelevant", Reason: ReasonExcludeMatched},
		{ID: "near-miss", Reason: ReasonExcludeMatched},
	})
}

